// n8n Cloud's free plan doesn't include the Environments feature, so all
// config lives here instead of $env.* — fill these in before activating the
// workflow. Never commit real secrets to source control; this file is meant
// to be edited locally after import, not checked in with real values.
return [{
  json: {
    ...$json,
    SUPABASE_URL: 'https://YOUR-PROJECT.supabase.co',
    SUPABASE_SERVICE_ROLE_KEY: 'YOUR_SERVICE_ROLE_KEY',
    SUPABASE_STORAGE_BUCKET: 'ticket-attachments',

    GEMINI_API_KEY: 'YOUR_GEMINI_API_KEY',

    JIRA_PROJECT_ID: 'YOUR_JIRA_PROJECT_ID',
    JIRA_ISSUETYPE_BUG_ID: 'YOUR_BUG_ISSUETYPE_ID',
    JIRA_ISSUETYPE_TASK_ID: 'YOUR_TASK_ISSUETYPE_ID',

    TELEGRAM_SUPPORT_GROUP_CHAT_ID: 'YOUR_TELEGRAM_CHAT_ID',

    TEAM_EMAIL_SERVICE_DESK: 'servicedesk@company.com',
    TEAM_EMAIL_NETWORK: 'network@company.com',
    TEAM_EMAIL_SECURITY: 'security@company.com',
    TEAM_EMAIL_INFRASTRUCTURE: 'infra@company.com',
    TEAM_EMAIL_APP_SUPPORT: 'appsupport@company.com'
  }
}];

// Supabase REST returns an array — normalize, call Gemini, parse its response,
// and apply the Jira business rules, all in one step.
const cfg = $('Config').first().json;
const raw = $input.first().json;
const ticket = Array.isArray(raw) ? raw[0] : raw;

const prompt = `You are an IT service-desk triage assistant. Analyze this ticket and return ONLY a compact JSON object (no markdown fences, no commentary) with keys: classification (short label), severity (one of Low, Medium, High, Critical based on business impact, may differ from the requester's chosen priority if the description suggests otherwise), summary (2-3 sentences, professional tone, suitable for a stakeholder-facing report), recommended_team (one of: Service Desk, Network Engineering, Security Operations, Infrastructure, Application Support), jira_recommended (true/false — true if this looks like a Security incident, an Infrastructure outage, or otherwise warrants formal issue tracking).

Ticket:
Subject: ${ticket.subject}
Description: ${ticket.description}
Category: ${ticket.category}
Requester priority: ${ticket.priority}
Department: ${ticket.department}`;

let parsed = {};
try {
  const aiResp = await this.helpers.httpRequest({
    method: 'POST',
    url: `https://generativelanguage.googleapis.com/v1beta/models/gemini-1.5-flash:generateContent?key=${cfg.GEMINI_API_KEY}`,
    headers: { 'Content-Type': 'application/json' },
    body: {
      contents: [{ parts: [{ text: prompt }] }],
      generationConfig: { temperature: 0.2, responseMimeType: 'application/json' }
    },
    json: true
  });
  const text = aiResp.candidates?.[0]?.content?.parts?.[0]?.text || '{}';
  parsed = JSON.parse(text);
} catch (e) {
  parsed = {
    classification: ticket.category,
    severity: ticket.priority,
    summary: 'AI summary unavailable — manual review recommended.',
    recommended_team: 'Service Desk',
    jira_recommended: ['High', 'Critical'].includes(ticket.priority)
  };
}

// Business rules — edit these to change when Jira issues get created.
const HIGH_PRIORITIES = ['High', 'Critical'];
const FORCE_JIRA_CATEGORIES = ['Security', 'Infrastructure'];
const ai_severity = parsed.severity || ticket.priority;
const jira_required = HIGH_PRIORITIES.includes(ticket.priority) ||
  HIGH_PRIORITIES.includes(ai_severity) ||
  FORCE_JIRA_CATEGORIES.includes(ticket.category) ||
  !!parsed.jira_recommended;

return [{
  json: {
    ...ticket,
    ai_classification: parsed.classification || ticket.category,
    ai_severity,
    ai_summary: parsed.summary || '',
    ai_recommended_team: parsed.recommended_team || 'Service Desk',
    jira_required
  }
}];

