// Builds a plain-text incident report and uploads it directly to Supabase
// Storage — no PDF renderer / Docker service required. Also resolves the
// destination team mailbox for the notification step.
const cfg = $('Config').first().json;
const t = $input.first().json;
const jiraKey = t.jira_issue_key || null;

const TEAM_EMAILS = {
  'Service Desk': cfg.TEAM_EMAIL_SERVICE_DESK,
  'Network Engineering': cfg.TEAM_EMAIL_NETWORK,
  'Security Operations': cfg.TEAM_EMAIL_SECURITY,
  'Infrastructure': cfg.TEAM_EMAIL_INFRASTRUCTURE,
  'Application Support': cfg.TEAM_EMAIL_APP_SUPPORT
};
const teamEmail = TEAM_EMAILS[t.ai_recommended_team] || cfg.TEAM_EMAIL_SERVICE_DESK;

const report = `IT SUPPORT INCIDENT REPORT
===========================
Ticket:        ${t.ticket_code}
Requester:     ${t.name} <${t.email}>
Department:    ${t.department}
Category:      ${t.category}
Priority:      ${t.priority}  (AI severity: ${t.ai_severity})
Recommended:   ${t.ai_recommended_team}
Jira:          ${jiraKey || 'Not raised'}
Status:        In Progress

Subject
-------
${t.subject}

AI Summary
----------
${t.ai_summary || 'Not available'}

Original Description
---------------------
${t.description}

Generated automatically by the IT Support System - ${new Date().toISOString()}
`;

const buffer = Buffer.from(report, 'utf-8');
const fileName = `${t.ticket_code}.txt`;

await this.helpers.httpRequest({
  method: 'POST',
  url: `${cfg.SUPABASE_URL}/storage/v1/object/${cfg.SUPABASE_STORAGE_BUCKET}/reports/${fileName}`,
  headers: {
    apikey: cfg.SUPABASE_SERVICE_ROLE_KEY,
    Authorization: `Bearer ${cfg.SUPABASE_SERVICE_ROLE_KEY}`,
    'Content-Type': 'text/plain',
    'x-upsert': 'true'
  },
  body: buffer
});

const reportUrl = `${cfg.SUPABASE_URL}/storage/v1/object/public/${cfg.SUPABASE_STORAGE_BUCKET}/reports/${fileName}`;

return [{
  json: { ...t, jira_issue_key: jiraKey, report_url: reportUrl, team_email: teamEmail },
  binary: { data: await this.helpers.prepareBinaryData(buffer, fileName, 'text/plain') }
}];
